/**
 * v0.5: the header every generated file starts with, and the hash that makes hand edits
 * detectable (G001). The hash covers the file's text without its hash line.
 */
import { VERSION } from "./version.js";

const K = new Uint32Array([
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
]);

export function sha256(data: Uint8Array): Uint8Array {
  const len = data.length;
  const padded = new Uint8Array(((len + 9 + 63) >> 6) << 6);
  padded.set(data);
  padded[len] = 0x80;
  const view = new DataView(padded.buffer);
  view.setUint32(padded.length - 8, Math.floor((len * 8) / 2 ** 32));
  view.setUint32(padded.length - 4, (len * 8) >>> 0);
  const h = new Uint32Array([0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19]);
  const w = new Uint32Array(64);
  const rotr = (x: number, n: number) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < padded.length; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = view.getUint32(off + i * 4);
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3);
      const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;
    }
    let [a, b, c, d, e, f, g, hh] = h;
    for (let i = 0; i < 64; i++) {
      const t1 = (hh + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) | 0;
      const t2 = ((rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      hh = g;
      g = f;
      f = e;
      e = (d + t1) | 0;
      d = c;
      c = b;
      b = a;
      a = (t1 + t2) | 0;
    }
    h[0] += a; h[1] += b; h[2] += c; h[3] += d; h[4] += e; h[5] += f; h[6] += g; h[7] += hh;
  }
  const out = new Uint8Array(32);
  const ov = new DataView(out.buffer);
  for (let i = 0; i < 8; i++) ov.setUint32(i * 4, h[i]);
  return out;
}

/** UTF-8 bytes of a string (the compiler runs in Node and the browser with no DOM or Node types). */
function utf8(text: string): Uint8Array {
  const out: number[] = [];
  for (const ch of text) {
    const c = ch.codePointAt(0)!;
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return new Uint8Array(out);
}

export function sha256Hex(text: string): string {
  return [...sha256(utf8(text))].map((b) => b.toString(16).padStart(2, "0")).join("");
}

export type CommentStyle = "#" | "//";

/** A file a generator writes. */
export interface GeneratedFile {
  /** Relative to the output folder (the backend's canon_generated/, or the frontend's src/canon/). */
  path: string;
  text: string;
  /** Written once if missing and never overwritten (main.py). */
  userOwned?: boolean;
}

const HASH_RE = /^(#|\/\/) canon-hash: sha256:([0-9a-f]{16})$/m;

/**
 * Finish a generated file: the header line, then the hash line, then the body. `from` names the
 * Canon source ("canon/todos.cn"), or is null for a file not generated from one (runtime files).
 */
export function finishGenerated(body: string, comment: CommentStyle, from: string | null): string {
  const head = `${comment} Generated by Canon ${VERSION}${from ? ` from ${from}` : ""}. Do not edit: change the Canon source.`;
  const text = `${head}\n${body}`;
  const hash = sha256Hex(text).slice(0, 16);
  return `${head}\n${comment} canon-hash: sha256:${hash}\n${body}`;
}

export interface GeneratedInfo {
  /** The file carries a Canon header and hash line. */
  generated: boolean;
  /** Its contents still match the hash (false: edited by hand). */
  intact: boolean;
}

export function inspectGenerated(text: string): GeneratedInfo {
  const lines = text.split("\n");
  if (!/^(#|\/\/) Generated by Canon /.test(lines[0] ?? "")) return { generated: false, intact: false };
  const m = HASH_RE.exec(lines[1] ?? "");
  if (!m) return { generated: true, intact: false };
  const without = [lines[0], ...lines.slice(2)].join("\n");
  return { generated: true, intact: sha256Hex(without).slice(0, 16) === m[2] };
}
